import {translations} from './i18n.mjs';
const entries={"manageMember":["Manage role","Hindura inshingano","Gérer le rôle"],"pendingInvites":["Unused invitations","Ubutumire butarakoreshejwe","Invitations non utilisées"],"revokeInvite":["Revoke invitation","Hagarika ubutumire","Révoquer invitation"],"membershipSaved":["Membership updated.","Inshingano zavuguruwe.","Adhésion mise à jour."],"operation":["Action","Igikorwa","Action"],"changeRole":["Change role","Hindura inshingano","Changer le rôle"],"transferChair":["Transfer chairperson responsibility","Guhererekanya ubuyobozi","Transférer la présidence"],"membershipInfo":["Changes take effect immediately. After transferring chairperson responsibility you become a regular member. Financial history is preserved.","Inshingano zihita zitangira. Nuhererekanya ubuyobozi uzaba umunyamuryango usanzwe. Amateka y’imari arabikwa.","Les changements sont immédiats. Après le transfert, vous devenez membre ordinaire. L’historique financier est conservé."],"transferConfirm":["I confirm transferring chairperson responsibility to this member.","Ndemeza guha uyu munyamuryango ubuyobozi.","Je confirme le transfert de la présidence à ce membre."],"revokeInfo":["This invitation will stop working. You can create another later.","Ubu butumire ntibuzongera gukora. Ushobora gutanga ubundi nyuma.","Cette invitation ne fonctionnera plus. Vous pourrez en créer une nouvelle."]};
